        "Oriente seu modelo mestre, ajuste as configurações da bandeja e pressione Gerar molde.",
        "Richten Sie Ihren Master aus, passen Sie die Tabletteinstellungen an und drücken Sie dann „Form erzeugen“.",
        "Orientez votre modèle maître, ajustez les paramètres du plateau, puis appuyez sur Générer le moule.",
