        "Orienta il master, regola le impostazioni del vassoio, quindi premi Genera stampo.",
        "Сориентируйте мастер, настройте параметры лотка, затем нажмите «Создать форму».",
        "マスターの向きとトレイ設定を調整してから、上の［モールドを生成］を押します。",
        "마스터 방향을 지정하고 트레이 설정을 조정한 다음 몰드 생성을 누르세요.",
