def _normalize_language(language: Any) -> str:
    normalized = str(language or LANGUAGE_EN).upper()
    if normalized not in {
        LANGUAGE_EN,
        LANGUAGE_AR,
        LANGUAGE_ES,
        LANGUAGE_PT,
        LANGUAGE_PT_BR,
        LANGUAGE_DE,
        LANGUAGE_FR,
        LANGUAGE_TR,
        LANGUAGE_IT,
        LANGUAGE_RU,
        LANGUAGE_JA,
        LANGUAGE_KO,
        LANGUAGE_ZH,
    }:
        return LANGUAGE_EN
    return normalized


def set_language(language: Any) -> str:
    global _CURRENT_LANGUAGE, _LANGUAGE_INITIALIZED
    _CURRENT_LANGUAGE = _normalize_language(language)
    _LANGUAGE_INITIALIZED = True
    try:
        _ENUM_CACHE.clear()
    except NameError:
        pass
    return _CURRENT_LANGUAGE


def initialize_language(prefs: Any | None = None) -> str:
    if prefs is None:
        try:
            from .environment import get_addon_preferences

            prefs = get_addon_preferences()
        except Exception:
            prefs = None

    return set_language(getattr(prefs, "language", LANGUAGE_EN) if prefs else LANGUAGE_EN)


def get_language(prefs: Any | None = None) -> str:
    if prefs is not None:
        return _normalize_language(getattr(prefs, "language", LANGUAGE_EN))
    if not _LANGUAGE_INITIALIZED:
        return initialize_language()
    return _CURRENT_LANGUAGE


def t(text: str, *, language: str | None = None, **kwargs: Any) -> str:
    lang = _normalize_language(language) if language is not None else get_language()
    translations = {
        LANGUAGE_AR: _AR,
        LANGUAGE_ES: _ES,
        LANGUAGE_PT: _PT,
        LANGUAGE_PT_BR: _PT_BR,
        LANGUAGE_DE: _DE,
        LANGUAGE_FR: _FR,
        LANGUAGE_TR: _TR,
        LANGUAGE_IT: _IT,
        LANGUAGE_RU: _RU,
        LANGUAGE_JA: _JA,
        LANGUAGE_KO: _KO,
        LANGUAGE_ZH: _ZH,
    }.get(lang)
    translated = translations.get(text, text) if translations else text
    formatted = translated.format(**kwargs) if kwargs else translated
    return _format_arabic_for_blender_display(formatted) if lang == LANGUAGE_AR else formatted


def prop_label(prop_name: str) -> str:
    return t(_PROPERTY_LABELS.get(prop_name, prop_name))


def prop_description(prop_name: str) -> str:
    return t(_PROPERTY_DESCRIPTIONS.get(prop_name, ""))


_ENUM_CACHE: dict[
    tuple[str, str],
    list[tuple[str, str, str] | tuple[str, str, str, int]],
] = {}

# Blender retains pointers to strings returned by dynamic EnumProperty callbacks.
# Keep every language selector result alive for the lifetime of the module so a
# popup cannot outlive the temporary list that supplied its labels.
_LANGUAGE_ENUM_CACHE: dict[str, list[tuple[str, str, str]]] = {}

# Keep the experimental implementation available without exposing it in the
# production selectors until its cost model is ready for general use.
SHOW_PRECISE_CLEAR_UNDERCUTS = False


def _enum_items(
    key: str,
    specs: tuple[
        tuple[str, str, str] | tuple[str, str, str, int],
        ...,
    ],
) -> list[tuple[str, str, str] | tuple[str, str, str, int]]:
    language = get_language()
    cache_key = (language, key)
    if cache_key not in _ENUM_CACHE:
        translated_items = []
        for item in specs:
            identifier, name, description, *optional_number = item
            translated_item = (
                identifier,
                t(name, language=language),
                t(description, language=language) if description else "",
            )
            if optional_number:
                translated_item += (optional_number[0],)
            translated_items.append(translated_item)
        _ENUM_CACHE[cache_key] = translated_items
    return _ENUM_CACHE[cache_key]


def language_items(self: Any, context: Any) -> list[tuple[str, str, str]]:
    language = get_language()
    if language not in _LANGUAGE_ENUM_CACHE:
        _LANGUAGE_ENUM_CACHE[language] = [
            (LANGUAGE_EN, "English", t("Use English labels", language=language)),
            (LANGUAGE_ES, "Español", t("Use Spanish labels", language=language)),
            (LANGUAGE_PT, "Português", t("Use Portuguese labels", language=language)),
            (
                LANGUAGE_PT_BR,
                "Português (Brasil)",
                t("Use Brazilian Portuguese labels", language=language),
            ),
            (LANGUAGE_DE, "Deutsch", t("Use German labels", language=language)),
            (LANGUAGE_FR, "Français", t("Use French labels", language=language)),
            (LANGUAGE_TR, "Türkçe", t("Use Turkish labels", language=language)),
            (LANGUAGE_IT, "Italiano", t("Use Italian labels", language=language)),
            (LANGUAGE_RU, "Русский", t("Use Russian labels", language=language)),
            (LANGUAGE_JA, "日本語", t("Use Japanese labels", language=language)),
            (LANGUAGE_KO, "한국어", t("Use Korean labels", language=language)),
            (LANGUAGE_ZH, "简体中文", t("Use Chinese labels", language=language)),
            (
                LANGUAGE_AR,
                _format_arabic_for_blender_display("العربية"),
                t("Use Arabic labels", language=language),
            ),
        ]
    return _LANGUAGE_ENUM_CACHE[language]


