def _apply_language_to_class(cls: Any) -> None:
    property_specs = cls.__dict__.get("_moldboxer_i18n_property_specs")
    if property_specs is None:
        property_specs = {}
        for property_name, deferred in getattr(cls, "__annotations__", {}).items():
            keywords = getattr(deferred, "keywords", None)
            if not isinstance(keywords, dict):
                continue
            property_specs[property_name] = {
                key: value
                for key, value in keywords.items()
                if key in {"name", "description", "items"}
            }
        cls._moldboxer_i18n_property_specs = property_specs

    for property_name, original_spec in property_specs.items():
        deferred = getattr(cls, "__annotations__", {}).get(property_name)
        keywords = getattr(deferred, "keywords", None)
        if not isinstance(keywords, dict):
            continue
        name = original_spec.get("name")
        description = original_spec.get("description")
        if isinstance(name, str):
            keywords["name"] = t(name)
        if isinstance(description, str):
            keywords["description"] = t(description)
        items = original_spec.get("items")
        if isinstance(items, (tuple, list)):
            keywords["items"] = type(items)(
                (
                    identifier,
                    t(item_name) if isinstance(item_name, str) else item_name,
                    (
                        t(item_description)
                        if isinstance(item_description, str)
                        else item_description
                    ),
                    *extra,
                )
                for identifier, item_name, item_description, *extra in items
            )

    class_name = getattr(cls, "__name__", "")
    label_spec = _CLASS_LABELS.get(class_name)
    if label_spec is None:
        # Keep the English source on the class so switching languages is reversible.
        label_spec = cls.__dict__.get("_moldboxer_i18n_label_spec")
        if label_spec is None:
            label = cls.__dict__.get("bl_label")
            if not isinstance(label, str):
                return
            label_spec = (label, cls.__dict__.get("bl_description"))
            cls._moldboxer_i18n_label_spec = label_spec

    label, description = label_spec
    cls.bl_label = t(label)
    if description is not None:
        cls.bl_description = t(description)


def apply_language_to_registered_classes(classes: Any | None = None) -> None:
    if classes is not None:
        for cls in classes:
            _apply_language_to_class(cls)
        return

    addon_package = __package__.rsplit(".source", 1)[0]
    for module in list(sys.modules.values()):
        module_name = getattr(module, "__name__", "")
        if not (module_name == addon_package or module_name.startswith(addon_package + ".")):
            continue
        for cls in tuple(vars(module).values()):
            if (not isinstance(cls, type) or cls.__module__ != module_name
                    or not ("bl_label" in cls.__dict__ or hasattr(cls, "bl_rna"))):
                continue
            _apply_language_to_class(cls)


def tag_redraw() -> None:
    window_manager = getattr(bpy.context, "window_manager", None)
    windows = getattr(window_manager, "windows", []) if window_manager else []
    for window in windows:
        screen = getattr(window, "screen", None)
        for area in getattr(screen, "areas", []) if screen else []:
            area.tag_redraw()


