def translate_progress_label(label):
    """Translate steps without modifying filenames or batch variant prefixes."""
    translated = t(label)
    if translated != label:
        return translated
    prefix, separator, step = label.rpartition(": ")
    return prefix + separator + t(step) if separator else translated
